import logging
from functools import wraps
from inspect import signature

from .connection import Connection
from .session import SSHSession

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


def ensure_connection(func):
    """
    Special wrapper created as the support for the ssh_keywords.
    When used on the method which uses the Connection or SSHSession
    it assures that the connection will be renewed in case of disconnection.
    """
    function = func
    func_signature = signature(function)
    if "connection" not in func_signature.parameters:
        raise TypeError('Decorated function does not have a "connection" parameter.')

    @wraps(function)
    def wrapper(*args, **kwargs):
        bound_args = func_signature.bind(*args, **kwargs)
        if "connection" in bound_args.arguments:
            connection = bound_args.arguments["connection"]
            keep_instance_connected(connection)

        return func(*args, **kwargs)

    return wrapper


def connect_and_log(connection_instance, warn):
    if warn:
        logger.warning("Reconnecting dead connection: %s", connection_instance)
    connection_instance.connect()


def keep_instance_connected(connection_or_session, warn=True):
    if isinstance(connection_or_session, SSHSession):
        connection_or_session = connection_or_session.connection
        proxy = connection_or_session.params.get("proxy")
        keep_instance_connected(proxy)
        if not connection_or_session.is_connected:
            connect_and_log(connection_or_session, warn)

    elif isinstance(connection_or_session, Connection):
        if not connection_or_session.is_connected:
            connect_and_log(connection_or_session, warn)

    elif connection_or_session is not None:
        raise TypeError(f"Unsupported connection object: {connection_or_session}")
